using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using NexaBook.Api.Data;using NexaBook.Api.Models;
namespace NexaBook.Api.Controllers;[ApiController,Route("api/users"),Authorize(Roles="Owner,Manager")]public class UsersController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult>Get()=>Ok(await db.Users.Where(x=>x.Role!=UserRole.Client).Select(x=>new{x.Id,x.FirstName,x.LastName,x.Email,x.Phone,Role=x.Role.ToString(),x.IsActive,x.CreatedAt}).ToListAsync());[HttpPost]public async Task<IActionResult>Add(User x){x.PasswordHash=BCrypt.Net.BCrypt.HashPassword(string.IsNullOrWhiteSpace(x.PasswordHash)?"Welcome123!":x.PasswordHash);db.Users.Add(x);await db.SaveChangesAsync();if(x.Role==UserRole.Staff)db.StaffProfiles.Add(new StaffProfile{UserId=x.Id,JobTitle="Staff"});await db.SaveChangesAsync();return Ok(x);}}
